    reg [1023:0] eword;
    reg [15:0]   ebeat;
    wire [63:0] nm;
    wire [1023:0] nb;
    wire pbad;
    generate if (!STATIC_PACKER) begin: g_legacy
    integer l;
    reg [63:0]   legacy_nm;
    reg [1023:0] legacy_nb;
    reg          legacy_pbad;
    always @(*) begin
        legacy_nm = xopen ? xm : 64'd0; legacy_nb = xb; legacy_pbad = 1'b0;
        for (l = 0; l < 8; l = l + 1)
            if (xw_we[l]) begin
                if (xw_addr[24*l + 6 +: 16] != xw_addr[6 +: 16] || !xw_we[0]) legacy_pbad = 1'b1;
                legacy_nb[16*xw_addr[24*l +: 6] +: 16] = bf16(xw_data[32*l +: 32]);
                if (legacy_nm[xw_addr[24*l +: 6]]) legacy_pbad = 1'b1;
                legacy_nm[xw_addr[24*l +: 6]] = 1'b1;
            end
        if (xw_we[0] && xopen && xw_addr[6 +: 16] != xbeat) legacy_pbad = 1'b1;   // previous beat abandoned partial
    end

    assign nm=legacy_nm; assign nb=legacy_nb; assign pbad=legacy_pbad;
    end else begin: g_static
    wire [127:0] lane_data;
    wire [63:0] lo_hit, hi_hit;
    for(genvar l=0;l<8;l=l+1) begin: g_decode
        for(genvar d=0;d<8;d=d+1) begin: g_digit
            assign lo_hit[8*l+d]=(xw_addr[24*l+:3]==3'(d));
            assign hi_hit[8*l+d]=xw_we[l] && (xw_addr[24*l+3+:3]==3'(d));
        end
    end
    for(genvar l=0;l<8;l=l+1) begin: g_bf
        assign lane_data[16*l+:16]=bf16(xw_data[32*l+:32]);
    end
