    always @(posedge ck or negedge rst_n) begin
        if (!rst_n) begin xopen <= 1'b0; xm <= 64'd0; emit <= 1'b0; end
        else begin
            emit <= 1'b0;
            if (xw_we != 8'd0) begin
                if (&nm) begin xopen <= 1'b0; xm <= 64'd0; emit <= 1'b1; end
                else begin xopen <= 1'b1; xm <= nm; end
            end
        end
