// Separate parameterized retained state, never an extra control pipeline edge.
(* keep_hierarchy="yes" *)
module qfd_dv_stream_open_copy #(parameter integer ID=0)(
 input wire ck,rst_n,we,complete,output reg q
);
 always @(posedge ck or negedge rst_n)
  if(!rst_n) q<=1'b0;
  else if(we) q<=!complete;
endmodule
